'use strict';
const WS={session:null,ready:false,error:'',tab:'drafts',sequence:0,drafts:[],caseRecords:[],priorityRecords:[],messages:[]};
Object.assign(names,{workspace:'Saved workspace',assistant:'AI assistant',measurements:'Trial results',team:'Team access'});
const originalRender=render;
const dateLabel=v=>new Date(v).toLocaleString('en-AU',{dateStyle:'medium',timeStyle:'short'});
const statusBadge=status=>`<span class="badge ${esc(status)}">${esc(status.replaceAll('_',' '))}</span>`;
async function api(path,options={}){
 let response;try{response=await fetch('/api'+path,{...options,headers:{'Content-Type':'application/json','X-PRG-Request':'1',...options.headers}});}catch{throw new Error('The saved workspace is unavailable. Your input is still on this page.');}
 let data;try{data=await response.json();}catch{throw new Error('The server did not return workspace data. Open the hosted app or run npm start.');}
 if(!response.ok)throw Object.assign(new Error(data.error||'The request failed.'),{status:response.status});return data;
}
const post=(path,value,method='POST')=>api(path,{method,body:JSON.stringify(value)});
function feedback(message,success=false){const box=$('#workspace-feedback');if(box){box.textContent=message;box.className='workspace-status'+(success?' success':'');}else toast(message);}
async function action(button,fn){button.disabled=true;try{await fn();}catch(e){feedback(e.message);}finally{if(button.isConnected)button.disabled=false;}}
function login(){return `<section class="panel sign-in-panel"><div class="step-label">SAVED WORKSPACE</div><h2>${WS.error?'Workspace connection':'Sign in to save your work'}</h2><p>${esc(WS.error||'Save drafts, record trial results, compare earlier cost assumptions and keep a review history attached to your account.')}</p><a class="button primary spaced" href="/signin-with-chatgpt?return_to=%2F%23workspace" target="_top">Sign in with ChatGPT →</a><p class="workspace-note">The hosted app uses platform sign-in and its existing private access policy. Opening index.html directly still provides the original offline demonstrations.</p>${['localhost','127.0.0.1'].includes(location.hostname)?'<div class="notice amber spaced">Local development uses simulated accounts. This is not a production login.</div>':''}</section>`;}
function memberIntro(){const u=WS.session.user;return `<div class="workspace-intro"><p><b>${esc(u.name)}</b> · ${esc(u.role)} · SQL storage enabled</p><p>Use fictional recruitment information. Saved drafts have server-checked permissions and versioned review history.</p>${WS.session.localDemo?`<div class="local-users"><b>Local account simulation:</b><a href="/signin-with-chatgpt?role=author">Author</a><a href="/signin-with-chatgpt?role=reviewer">Reviewer</a><a href="/signin-with-chatgpt?role=owner">Owner</a></div>`:''}</div>`;}
function workspaceHeader(title,description){return header('SHARED WORKFLOWS. RECORDED DECISIONS.',title,description)+memberIntro()+'<div id="workspace-feedback" class="workspace-status" role="status" aria-live="polite"></div>';}
render=function(){
 const page=location.hash.slice(1).split('/')[0]||'overview';WS.sequence++;
 if(!['workspace','assistant','measurements','team'].includes(page)){originalRender();decorate();return;}
 $('#page-name').textContent=names[page];document.title=names[page]+' · PRG Opportunity Lab';document.querySelectorAll('[data-page]').forEach(a=>{a.classList.toggle('active',a.dataset.page===page);if(a.dataset.page===page)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
 if(!WS.ready){$('#main').innerHTML='<section class="panel"><h2>Connecting to your workspace…</h2></section>';return;}
 if(!WS.session){$('#main').innerHTML=login();return;}
 const seq=WS.sequence;$('#main').innerHTML=workspaceHeader(names[page],page==='assistant'?'Ask about the project, challenge assumptions or discuss a selected saved draft.':'Records are saved to your account and survive refreshes.')+'<section id="workspace-content" class="panel"><p>Loading records…</p></section>';
 ({workspace:showWorkspace,assistant:showAssistant,measurements:showMeasurements,team:showTeam}[page])(seq).catch(e=>{if(seq===WS.sequence){$('#workspace-content').innerHTML='<p>Records could not be loaded. Your existing data has not been changed.</p><button class="button spaced" id="reload-workspace">Try again</button>';$('#reload-workspace').onclick=()=>render();feedback(e.message);}});
};
function navTabs(){return `<div class="workspace-tabs">${[['drafts','Drafts & approvals'],['cases','Saved business cases'],['priorities','Priority reviews']].map(([v,n])=>`<button class="button ${WS.tab===v?'active':''}" data-wtab="${v}">${n}</button>`).join('')}${WS.session.user.role==='admin'?'<a class="button" href="#team">Team access</a>':''}</div>`;}
async function showWorkspace(seq){const selected=location.hash.split('/')[1];if(selected)return showDraft(selected,seq);
 const result=await api(WS.tab==='cases'?'/cases':WS.tab==='priorities'?'/priorities':'/drafts');if(seq!==WS.sequence)return;
 const content=$('#workspace-content');content.className='';content.innerHTML=navTabs()+'<section class="panel" id="saved-list"></section>';
 document.querySelectorAll('[data-wtab]').forEach(b=>b.onclick=()=>{WS.tab=b.dataset.wtab;render();});const list=$('#saved-list');
 if(WS.tab==='drafts'){WS.drafts=result.drafts;list.innerHTML=`<div class="section-heading"><h2>Saved drafts</h2><a class="button" href="#trials">Create from trial studio →</a></div><p>Authors see their own drafts. Reviewers can inspect drafts in this private workspace. Editing any version resets its approval.</p>${result.drafts.length?result.drafts.map(d=>`<div class="saved-item"><div><h3>${esc(d.title)}</h3><p>${esc(trialMeta[d.type][0])} · ${esc(d.author)} · version ${d.version}</p><p>${dateLabel(d.updated_at)} ${statusBadge(d.status)}</p></div><a class="button" href="#workspace/${d.id}">Open →</a></div>`).join(''):'<div class="empty"><h3>No saved drafts yet</h3><p>Open a workflow in the trial studio and select “Save synthetic draft”.</p></div>'}`;
 }else if(WS.tab==='cases'){WS.caseRecords=result.cases;list.innerHTML=`<div class="section-heading"><h2>Saved business cases</h2><a class="button" href="#business">Open calculator →</a></div><p>Each saved version preserves all assumptions and server-calculated results. Illustrative capacity value is not measured cash savings.</p>${result.cases.map(c=>`<div class="saved-item"><div><h3>${esc(c.name)}</h3><p>${dateLabel(c.created_at)} · ${money(JSON.parse(c.results)[0].net1)} existing-tools year-one net capacity value</p></div><button class="button" data-load-case="${c.id}">Load assumptions →</button></div>`).join('')||'<div class="empty"><p>No saved cost scenarios. Save one from the business-case page.</p></div>'}`;document.querySelectorAll('[data-load-case]').forEach(b=>b.onclick=()=>{const record=JSON.parse(WS.caseRecords.find(c=>c.id===b.dataset.loadCase).assumptions);state.inputs=record.inputs;state.paths=record.paths.map((p,i)=>({...D.paths[i],...p}));location.hash='business';toast('Saved assumptions loaded. Save again to create a new historical version.');});
 }else{WS.priorityRecords=result.snapshots;const latest=result.snapshots[0]?JSON.parse(result.snapshots[0].scores):D.opportunities;list.innerHTML=`<h2>Review the opportunity scores</h2><p>Change the 1–5 judgments, then save a dated snapshot. The server recalculates each weighted total.</p><div class="field spaced"><label for="priority-name">Review name</label><input id="priority-name" maxlength="160" value="Discovery priority review"></div><div class="table-wrap"><table><thead><tr><th>Opportunity</th><th>Impact</th><th>Feasibility</th><th>Adoption</th><th>Risk</th></tr></thead><tbody>${D.opportunities.map(o=>{const s=latest.find(x=>x.id===o.id)||o;return `<tr><td>${o.id} · ${o.title}</td>${['impact','feasibility','adoption','risk'].map(k=>`<td><input class="priority-input" aria-label="${o.id} ${k}" data-priority="${o.id}" data-dimension="${k}" value="${s[k]}" type="number" min="1" max="5" step="1"></td>`).join('')}</tr>`;}).join('')}</tbody></table></div><button class="button primary spaced" id="save-priorities">Save priority review</button><h3 class="spaced">Previous reviews</h3>${result.snapshots.map(s=>`<details><summary>${esc(s.name)} · ${dateLabel(s.created_at)}</summary><p>${JSON.parse(s.scores).sort((a,b)=>b.score-a.score).map(o=>`${o.id}: ${o.score}/100`).join(' · ')}</p></details>`).join('')||'<p>No saved reviews.</p>'}`;$('#save-priorities').onclick=e=>action(e.target,async()=>{const scores=D.opportunities.map(o=>({id:o.id,...Object.fromEntries(['impact','feasibility','adoption','risk'].map(k=>[k,Number(document.querySelector(`[data-priority="${o.id}"][data-dimension="${k}"]`).value)]))}));await post('/priorities',{name:$('#priority-name').value,scores});toast('Priority review saved.');render();});}
}
async function showDraft(draftId,seq){const result=await api('/drafts/'+encodeURIComponent(draftId));if(seq!==WS.sequence)return;const d=result.draft,s=JSON.parse(d.source),owner=d.owner_id===WS.session.user.id,isReviewer=['admin','reviewer'].includes(WS.session.user.role);const content=$('#workspace-content');content.className='';
 content.innerHTML=`<div class="workspace-toolbar"><a class="button" href="#workspace">← All drafts</a>${statusBadge(d.status)}<span class="workspace-count">Version ${d.version} · ${dateLabel(d.updated_at)}</span></div><div class="saved-grid spaced"><section class="panel"><h2>${esc(d.title)}</h2><p>Source facts and the edited output are saved together. A change creates a new version and requires another review.</p><form id="saved-editor" class="spaced"><div class="field"><label for="saved-title">Draft title</label><input id="saved-title" maxlength="160" value="${esc(d.title)}" ${owner?'':'readonly'}></div><details><summary>Source fields</summary>${Object.entries(s).filter(([k])=>k!=='source').map(([k,v])=>`<div class="field"><label for="saved-${k}">${esc(k)}</label><input id="saved-${k}" data-saved-source="${k}" value="${esc(v)}" ${owner?'':'readonly'}></div>`).join('')}</details><div class="field spaced"><label for="saved-output">Draft text</label><textarea id="saved-output" class="editor-output" maxlength="16000" ${owner?'':'readonly'}>${esc(d.output)}</textarea></div><div class="draft-actions">${owner?'<button class="button primary" type="submit">Save new version</button>':''}${owner&&['draft','changes_requested'].includes(d.status)?'<button class="button" type="button" id="submit-draft">Submit for review</button>':''}${d.status==='approved'?`<a class="button" id="approved-export" href="/api/drafts/${d.id}/export">Export approved version ↓</a>`:''}</div><p id="unsaved-warning" class="workspace-note" role="status"></p></form>${result.validation.blocked?`<div class="notice amber spaced"><b>Approval checks need attention</b><ul class="blocked-list">${result.validation.flags.map(f=>`<li>${esc(f)}</li>`).join('')}</ul></div>`:''}</section><aside><section class="panel"><h2>Reviewer decision</h2>${isReviewer&&d.status==='submitted'?`<div class="field spaced"><label for="review-note">Review note</label><textarea id="review-note" class="review-note" placeholder="What did you check, or what needs changing?"></textarea></div><label class="checks"><input id="server-review-check" type="checkbox"> I checked the source facts and wording for this version.</label><div class="draft-actions"><button class="button primary" id="server-approve">Approve version</button><button class="button" id="request-changes">Request changes</button></div>`:`<p>${d.status==='approved'?'This version has a recorded approval.':d.status==='submitted'?'A reviewer or administrator must record a decision.':'The author must save and submit a complete draft before review.'}</p>`}<p class="workspace-note">Approvals are checked by the server. A browser checkbox alone cannot authorise an export.</p><a class="button small spaced" href="#assistant/${d.id}">Discuss with AI assistant →</a></section><section class="panel spaced"><h2>Version & review history</h2>${result.events.map(event=>`<div class="history-card"><b>${esc(event.kind.replaceAll('_',' '))} · version ${event.version}</b><p>${esc(event.actor)} · ${esc(event.note)}</p><small>${dateLabel(event.created_at)}</small><details><summary>View recorded output</summary><div class="snapshot-text">${esc(JSON.parse(event.snapshot).output)}</div></details></div>`).join('')}</section></aside></div>`;
 let dirty=false;$('#saved-editor').oninput=()=>{dirty=true;$('#unsaved-warning').textContent='Unsaved changes. Save a new version before submitting or exporting.';for(const selector of ['#submit-draft','#server-approve','#request-changes'])if($(selector))$(selector).disabled=true;if($('#approved-export'))$('#approved-export').hidden=true;};
 $('#saved-editor').onsubmit=e=>{e.preventDefault();if(!owner)return;action(e.submitter,async()=>{const source={};document.querySelectorAll('[data-saved-source]').forEach(el=>source[el.dataset.savedSource]=el.value);await post('/drafts/'+d.id,{version:d.version,title:$('#saved-title').value,source,output:$('#saved-output').value},'PATCH');toast('New version saved. Previous approvals do not apply.');render();});};
 if($('#submit-draft'))$('#submit-draft').onclick=e=>action(e.target,async()=>{if(dirty)throw new Error('Save your changes first.');await post('/drafts/'+d.id+'/submit',{version:d.version});toast('Submitted for reviewer approval.');render();});
 for(const [selector,decision] of [['#server-approve','approve'],['#request-changes','request_changes']])if($(selector))$(selector).onclick=e=>action(e.target,async()=>{await post('/drafts/'+d.id+'/review',{version:d.version,decision,note:$('#review-note').value,confirmed:$('#server-review-check').checked});toast(decision==='approve'?'Approval recorded for this version.':'Changes requested.');render();});
}
async function showMeasurements(seq){const result=await api('/measurements');if(seq!==WS.sequence)return;const rows=result.measurements,valid=rows.filter(r=>r.accepted&&r.critical_errors===0),reductions=valid.map(r=>(r.baseline-r.assisted)/r.baseline*100).sort((a,b)=>a-b);const median=reductions.length?(reductions[Math.floor((reductions.length-1)/2)]+reductions[Math.ceil((reductions.length-1)/2)])/2:null;const content=$('#workspace-content');content.className='';content.innerHTML=`<div class="notice">Record observations from a synthetic or approved trial. Total assisted time must include review and corrections. These records are private to your account; no PRG results are preloaded.</div><div class="measurement-summary"><div class="stat"><div class="stat-label">Recorded cases</div><strong>${rows.length}</strong></div><div class="stat"><div class="stat-label">Accepted, no critical errors</div><strong>${valid.length}</strong></div><div class="stat"><div class="stat-label">Median time reduction*</div><strong>${median===null?'—':median.toFixed(1)+'%'}</strong></div></div><div class="saved-grid"><section class="panel"><h2>Record a trial observation</h2><form id="measurement-form" class="spaced"><div class="field"><label for="m-label">Case label (synthetic reference)</label><input id="m-label" required maxlength="160" placeholder="BESS brief — test 01"></div><div class="field"><label for="m-workflow">Workflow</label><select id="m-workflow">${Object.entries(trialMeta).map(([k,[v]])=>`<option value="${k}">${v}</option>`).join('')}</select></div><div class="field-row">${[['Baseline total minutes','baseline','10'],['Assisted total minutes','assisted','6'],['Review minutes (included in total)','review','2'],['Corrections','corrections','0'],['Critical errors','errors','0']].map(([label,k,v])=>`<div class="field"><label for="m-${k}">${label}</label><input id="m-${k}" type="number" min="${k==='baseline'?'.01':'0'}" max="1440" step="${['corrections','errors'].includes(k)?'1':'.01'}" value="${v}" required></div>`).join('')}</div><label class="checks"><input id="m-accepted" type="checkbox"> The reviewer accepted the output.</label><div class="field"><label for="m-notes">Observation notes</label><textarea id="m-notes" maxlength="2000" placeholder="What worked? What required correction?"></textarea></div><button class="button primary">Save observation</button></form></section><section class="panel"><h2>How to interpret the results</h2><p>*Median percentage reduction is calculated only for accepted cases without critical errors. Negative values mean the assisted task took longer. It does not prove causation or a cash saving.</p><p class="spaced">Keep unsuccessful cases in the record. Review acceptance, errors and staff feedback alongside time. A small test set is not proof of production reliability.</p><button class="button spaced" id="export-measurements">Export observations ↓</button></section></div><section class="panel spaced"><h2>Observation history</h2><div class="table-wrap spaced"><table class="measurement-table"><thead><tr><th>Case</th><th>Baseline</th><th>Assisted total</th><th>Review included</th><th>Corrections / critical</th><th>Accepted</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.label)}<small>${dateLabel(r.created_at)}</small></td><td>${r.baseline} min</td><td>${r.assisted} min</td><td>${r.review} min</td><td>${r.corrections} / ${r.critical_errors}</td><td>${r.accepted?'Yes':'No'}</td></tr>`).join('')||'<tr><td colspan="6">No observations saved yet.</td></tr>'}</tbody></table></div></section>`;
 $('#measurement-form').onsubmit=e=>{e.preventDefault();action(e.submitter,async()=>{await post('/measurements',{label:$('#m-label').value,workflow:$('#m-workflow').value,baseline:+$('#m-baseline').value,assisted:+$('#m-assisted').value,review:+$('#m-review').value,corrections:+$('#m-corrections').value,criticalErrors:+$('#m-errors').value,accepted:$('#m-accepted').checked,notes:$('#m-notes').value});toast('Trial observation saved.');render();});};$('#export-measurements').onclick=()=>download('prg-trial-observations.json',JSON.stringify(rows,null,2),'application/json');
}
function chatMarkup(messages){return messages.map(m=>`<div class="message ${m.role}"><small>${m.role==='user'?'YOU':'AI ASSISTANT · '+esc(m.model)}</small>${esc(m.content)}</div>`).join('')||'<div class="empty"><h3>Make the next decision clearer.</h3><p>Ask about the project, pilot design, costs or a selected synthetic draft.</p></div>';}
async function showAssistant(seq){const [chat,drafts]=await Promise.all([api('/assistant/messages'),api('/drafts')]);if(seq!==WS.sequence)return;WS.messages=chat.messages;const selected=location.hash.split('/')[1]||'';const content=$('#workspace-content');content.className='assistant-layout';content.innerHTML=`<section class="panel"><div class="section-heading"><h2>PRG assistant</h2><span class="badge ${WS.session.aiConfigured?'':'amber'}">${WS.session.aiConfigured?'API key configured':'API connection needed'}</span></div>${!WS.session.aiConfigured?'<div class="notice amber">Live AI is not connected yet. The server integration is ready, but an administrator must configure an API key and model. This screen does not substitute canned answers for AI.</div>':''}<div class="chat-log" id="chat-log" aria-live="polite">${chatMarkup(chat.messages)}</div><form id="assistant-form"><div class="field"><label for="assistant-draft">Include one saved draft (optional)</label><select id="assistant-draft"><option value="">Project context only</option>${drafts.drafts.map(d=>`<option value="${d.id}" ${d.id===selected?'selected':''}>${esc(d.title)} · v${d.version}</option>`).join('')}</select></div><div class="field"><label for="assistant-message">Your question</label><textarea id="assistant-message" maxlength="4000" rows="4" required placeholder="What should I validate before recommending this workflow?"></textarea></div><label class="checks"><input id="assistant-confirm" type="checkbox" required> My message and selected draft contain only synthetic or public information. I agree to send them to the configured AI provider.</label><button class="button primary" id="ask-assistant" ${WS.session.aiConfigured?'':'disabled'}>Ask assistant ↗</button></form><div class="chat-suggestions">${['Explain the savings assumptions simply.','Suggest a test plan for candidate updates.','What should I ask a recruiter in week one?'].map(q=>`<button class="button small" data-question="${q}">${q}</button>`).join('')}</div></section><aside><section class="panel"><h2>What the assistant can do</h2><ul><li>Explain project assumptions and trade-offs.</li><li>Suggest improvements to a selected draft.</li><li>Help design a controlled trial.</li><li>Identify questions for discovery.</li></ul><div class="notice">It cannot send messages, change records, approve work or make hiring decisions. Check every factual claim before use.</div><p class="workspace-note">Only your conversation and an explicitly selected draft are supplied. Up to 12 recent messages provide context. Replies are saved privately to your account. Limit: 20 requests per account and 100 per workspace per UTC day; failed attempts also count.</p></section><section class="panel spaced"><h2>Reference material provided</h2><p>Public source notes reviewed 25 September 2026. The assistant does not browse live.</p>${chat.references.map(r=>`<a class="source-link" href="${r.url}" target="_blank" rel="noreferrer">[${r.id}] ${r.title} ↗</a>`).join('')}</section></aside>`;
 document.querySelectorAll('[data-question]').forEach(b=>b.onclick=()=>{$('#assistant-message').value=b.dataset.question;$('#assistant-message').focus();});
 $('#assistant-form').onsubmit=e=>{e.preventDefault();const composer=$('#assistant-message'),question=composer.value.trim(),draftId=$('#assistant-draft').value;action(e.submitter,async()=>{e.submitter.textContent='Preparing a response…';try{const result=await post('/assistant',{message:question,draftId: draftId||undefined,syntheticOnly:$('#assistant-confirm').checked});WS.messages.push({role:'user',content:question},{role:'assistant',content:result.answer,model:result.model});if(seq!==WS.sequence)return;$('#chat-log').innerHTML=chatMarkup(WS.messages);$('#chat-log').scrollTop=$('#chat-log').scrollHeight;composer.value='';feedback('Response saved to your account.',true);}finally{if(e.submitter.isConnected)e.submitter.textContent='Ask assistant ↗';}});};
}
async function showTeam(seq){const result=await api('/users');if(seq!==WS.sequence)return;$('#workspace-content').innerHTML=`<h2>Team access</h2><p>Platform sharing controls who may enter this private site. After an allowed person signs in, the owner can grant the reviewer role here. Members can edit their own drafts; reviewers can inspect and approve submitted drafts.</p><div class="table-wrap spaced"><table><thead><tr><th>Person</th><th>Role</th><th>Action</th></tr></thead><tbody>${result.users.map(u=>`<tr><td>${esc(u.name)}<small>${esc(u.email)}</small></td><td>${u.id===WS.session.user.id?'Owner / administrator':`<select class="role-select" aria-label="Role for ${esc(u.name)}" data-role-user="${u.id}"><option value="member" ${u.role==='member'?'selected':''}>Member</option><option value="reviewer" ${u.role==='reviewer'?'selected':''}>Reviewer</option></select>`}</td><td>${u.id===WS.session.user.id?'Configured owner':`<button class="button small" data-save-role="${u.id}">Save role</button>`}</td></tr>`).join('')}</tbody></table></div><a class="button spaced" href="#workspace">Back to workspace</a>`;document.querySelectorAll('[data-save-role]').forEach(b=>b.onclick=()=>action(b,async()=>{await post('/users',{id:b.dataset.saveRole,role:document.querySelector(`[data-role-user="${b.dataset.saveRole}"]`).value},'PATCH');feedback('Role saved.',true);}));}
function decorate(){const page=location.hash.slice(1).split('/')[0]||'overview';
 if(page==='trials'&&$('#trial-form')&&!$('#cloud-draft')){const block=document.createElement('div');block.className='cloud-save';block.id='cloud-draft';block.innerHTML='<h3>Keep this work</h3><p>Save the current synthetic source fields and a fresh template draft to the SQL workspace.</p><button class="button" type="button" id="save-cloud-draft">Save synthetic draft →</button>';$('#trial-form').append(block);$('#save-cloud-draft').onclick=e=>action(e.target,async()=>{if(!WS.session){location.hash='workspace';return;}const source={};document.querySelectorAll('[data-field]').forEach(el=>source[el.dataset.field]=el.value);const result=await post('/drafts',{type:state.trial,source,title:source.role,syntheticOnly:true});location.hash='workspace/'+result.draft.id;});}
 if(page==='business'&&$('.cost-layout')&&!$('#cloud-case')){const block=document.createElement('section');block.id='cloud-case';block.className='panel spaced';block.innerHTML='<h2>Save this business case</h2><p>Keep these assumptions and recalculated results as a dated version in your account.</p><div class="field spaced"><label for="case-name">Scenario name</label><input id="case-name" maxlength="160" value="Initial discovery assumptions"></div><button class="button primary" id="save-cloud-case">Save scenario</button> <a class="button" href="#workspace">View saved versions →</a>';$('.cost-layout').after(block);$('#save-cloud-case').onclick=e=>action(e.target,async()=>{if(!WS.session){location.hash='workspace';return;}await post('/cases',{name:$('#case-name').value,inputs:state.inputs,paths:state.paths});toast('Scenario and server-calculated results saved.');});}
}
async function connect(){if(location.protocol==='file:'){WS.ready=true;WS.error='Saved features need a server. Open the hosted app or run npm start.';render();return;}try{WS.session=await api('/me');const u=WS.session.user;$('#account-status').innerHTML=`<a href="#workspace">${esc(u.name)} · ${esc(u.role)}</a> <a aria-label="Sign out" href="/signout-with-chatgpt?return_to=%2F" target="_top">↪</a>`;}catch(e){WS.error=e.status===401?'':e.message;$('#account-status').innerHTML='<a href="/signin-with-chatgpt?return_to=%2F%23workspace" target="_top">Sign in</a>';}WS.ready=true;render();}
render();connect();
